import { json } from '@tanstack/react-start'
import { createAPIFileRoute } from '@tanstack/react-start/api'
import { postsStore } from './posts'

export const APIRoute = createAPIFileRoute('/api/posts/$id/like')({
  POST: async ({ request, params }) => {
    const { id } = params

    let body: { fail?: boolean } = {}
    try {
      body = await request.json()
    } catch {
      // no body
    }

    if (body.fail === true) {
      return json({ error: 'Simulated failure' }, { status: 500 })
    }

    const post = postsStore.find((p) => p.id === id)
    if (!post) {
      return json({ error: 'Post not found' }, { status: 404 })
    }

    post.likes += 1
    return json(post)
  },
})

import { createFileRoute } from '@tanstack/react-router'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { useState } from 'react'

export const Route = createFileRoute('/')({
  component: Home,
})

interface Post {
  id: string
  title: string
  likes: number
}

async function fetchPosts(): Promise<Post[]> {
  const res = await fetch('/api/posts')
  if (!res.ok) throw new Error('Failed to fetch posts')
  return res.json()
}

async function likePost(args: { id: string; fail: boolean }): Promise<Post> {
  const res = await fetch(`/api/posts/${args.id}/like`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ fail: args.fail }),
  })
  if (!res.ok) {
    const err = await res.json().catch(() => ({}))
    throw new Error((err as any).error ?? 'Failed to like post')
  }
  return res.json()
}

function PostCard({ post }: { post: Post }) {
  const queryClient = useQueryClient()
  const [simulateFailure, setSimulateFailure] = useState(false)

  const mutation = useMutation({
    mutationFn: likePost,

    onMutate: async ({ id }) => {
      // Cancel any outgoing refetches so they don't overwrite our optimistic update
      await queryClient.cancelQueries({ queryKey: ['posts'] })

      // Snapshot the previous value
      const previousPosts = queryClient.getQueryData<Post[]>(['posts'])

      // Optimistically update the cache
      queryClient.setQueryData<Post[]>(['posts'], (old) =>
        old?.map((p) => (p.id === id ? { ...p, likes: p.likes + 1 } : p)),
      )

      // Return context with snapshot for rollback
      return { previousPosts }
    },

    onError: (_err, _variables, context) => {
      // Roll back on error
      if (context?.previousPosts) {
        queryClient.setQueryData<Post[]>(['posts'], context.previousPosts)
      }
    },

    onSettled: () => {
      // Always refetch after mutation to ensure consistency
      queryClient.invalidateQueries({ queryKey: ['posts'] })
    },
  })

  return (
    <div
      style={{
        border: '1px solid #ddd',
        borderRadius: '8px',
        padding: '20px',
        maxWidth: '400px',
        margin: '20px auto',
        fontFamily: 'sans-serif',
      }}
    >
      <h2 style={{ marginTop: 0 }}>{post.title}</h2>

      <p>
        Likes:{' '}
        <strong data-testid="like-count">{post.likes}</strong>
      </p>

      <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
        <button
          data-testid="like-button"
          onClick={() =>
            mutation.mutate({ id: post.id, fail: simulateFailure })
          }
          disabled={mutation.isPending}
          style={{
            padding: '8px 20px',
            backgroundColor: '#4f46e5',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: mutation.isPending ? 'not-allowed' : 'pointer',
            fontSize: '14px',
          }}
        >
          {mutation.isPending ? 'Liking…' : '👍 Like'}
        </button>

        <label
          style={{ display: 'flex', alignItems: 'center', gap: '6px', cursor: 'pointer' }}
        >
          <input
            type="checkbox"
            data-testid="simulate-failure"
            checked={simulateFailure}
            onChange={(e) => setSimulateFailure(e.target.checked)}
          />
          Simulate Failure
        </label>
      </div>

      {mutation.isError && (
        <p style={{ color: 'red', marginTop: '12px', fontSize: '14px' }}>
          ⚠️ Error: {(mutation.error as Error).message} — like count rolled back.
        </p>
      )}
    </div>
  )
}

function Home() {
  const { data: posts, isLoading, isError } = useQuery({
    queryKey: ['posts'],
    queryFn: fetchPosts,
  })

  if (isLoading) return <p style={{ fontFamily: 'sans-serif', padding: '20px' }}>Loading posts…</p>
  if (isError) return <p style={{ fontFamily: 'sans-serif', padding: '20px', color: 'red' }}>Failed to load posts.</p>

  return (
    <div style={{ padding: '20px' }}>
      <h1 style={{ textAlign: 'center', fontFamily: 'sans-serif' }}>
        TanStack Query — Optimistic Likes
      </h1>
      {posts?.map((post) => <PostCard key={post.id} post={post} />)}
    </div>
  )
}

